page_settings.custom_css:
selector .fmg5{
  --fmg5-primary:#f6071a;
  --fmg5-primary-strong:#d90516;
  --fmg5-secondary:#fe8b15;
  --fmg5-accent:#ffc36b;
  --fmg5-ink:#111114;
  --fmg5-ink-soft:#47433f;
  --fmg5-muted:#756d66;
  --fmg5-line:rgba(17,17,20,.10);
  --fmg5-white:#ffffff;
  --fmg5-surface:#ffffff;
  --fmg5-surface-2:#f2eee8;
  --fmg5-page:#f7f2eb;
  --fmg5-gradient-brand:linear-gradient(135deg,var(--fmg5-secondary) 0%,var(--fmg5-primary) 100%);
  --fmg5-gradient-dark:linear-gradient(135deg,#16161b 0%,#2a1718 50%,#4a130e 100%);
  --fmg5-gradient-surface:linear-gradient(180deg,rgba(255,255,255,.96) 0%,rgba(242,238,232,.98) 100%);
  --fmg5-text-sm:clamp(.875rem,.84rem + .18vw,.98rem);
  --fmg5-text-base:clamp(1rem,.96rem + .22vw,1.08rem);
  --fmg5-text-md:clamp(1.0625rem,1rem + .3vw,1.18rem);
  --fmg5-text-lg:clamp(1.25rem,1.12rem + .6vw,1.56rem);
  --fmg5-text-xl:clamp(1.5rem,1.24rem + 1vw,2.1rem);
  --fmg5-text-2xl:clamp(1.9rem,1.45rem + 1.8vw,3rem);
  --fmg5-text-3xl:clamp(2.3rem,1.7rem + 2.8vw,4.25rem);
  --fmg5-radius-sm:.75rem;
  --fmg5-radius-md:1rem;
  --fmg5-radius-lg:1.375rem;
  --fmg5-radius-xl:1.875rem;
  --fmg5-radius-pill:999px;
  --fmg5-shadow-sm:0 8px 20px rgba(17,17,20,.06);
  --fmg5-shadow-md:0 18px 38px rgba(17,17,20,.08);
  --fmg5-shadow-lg:0 28px 70px rgba(17,17,20,.16);
  color:var(--fmg5-ink);
  font-size:var(--fmg5-text-base);
}
html {scroll-behavior: smooth;} selector .fmg5 *{box-sizing:border-box;}
selector .fmg5 .fmg5-shell{
  background:
    radial-gradient(circle at top left, rgba(254,139,21,.12), transparent 26%),
    radial-gradient(circle at top right, rgba(246,7,26,.08), transparent 24%),
    linear-gradient(180deg,#faf6f1 0%,#f5f0e9 100%);
  padding:clamp(1rem,.8rem + 1vw,1.5rem);
  border-radius:2rem;
}
selector .fmg5 .fmg5-hero,
selector .fmg5 .fmg5-dark{
  background:var(--fmg5-gradient-dark);
  color:var(--fmg5-white);
  border-radius:max(var(--fmg5-radius-xl),2.25rem);
  box-shadow:var(--fmg5-shadow-lg);
  padding:clamp(1.4rem,1rem + 2vw,2rem);
}
selector .fmg5 .fmg5-card,
selector .fmg5 .fmg5-proof,
selector .fmg5 .fmg5-soft,
selector .fmg5 .fmg5-gallery-card,
selector .fmg5 .fmg5-faq details{
  border:1px solid var(--fmg5-line);
  border-radius:var(--fmg5-radius-lg);
  background:var(--fmg5-gradient-surface);
  box-shadow:var(--fmg5-shadow-sm);
}
selector .fmg5 .fmg5-card,
selector .fmg5 .fmg5-proof,
selector .fmg5 .fmg5-soft,
selector .fmg5 .fmg5-gallery-card{padding:1.2rem;}
selector .fmg5 .fmg5-kicker{
  display:inline-block;
  padding:.45rem .8rem;
  border-radius:999px;
  background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.14);
  color:#fff;
  font-size:var(--fmg5-text-sm);
  font-weight:700;
}
selector .fmg5 .fmg5-title{
  margin:.8rem 0 1rem;
  font-size:var(--fmg5-text-3xl);
  line-height:1.05;
  text-transform:uppercase;
  color:#fff;
}
selector .fmg5 .fmg5-section-title{
  margin:0 0 .8rem;
  font-size:var(--fmg5-text-2xl);
  line-height:1.1;
  text-transform:uppercase;
  color:var(--fmg5-ink);
}
selector .fmg5 .fmg5-dark .fmg5-section-title{color:#fff;}
selector .fmg5 .fmg5-sub{
  font-size:var(--fmg5-text-lg);
  line-height:1.5;
  color:rgba(255,255,255,.92);
}
selector .fmg5 .fmg5-muted{color:var(--fmg5-ink-soft);}
selector .fmg5 .fmg5-note{font-size:var(--fmg5-text-sm);color:var(--fmg5-muted);}
selector .fmg5 .fmg5-security{font-size:var(--fmg5-text-sm);color:rgba(255,255,255,.78);margin-top:.9rem;}
selector .fmg5 .fmg5-grid-2,
selector .fmg5 .fmg5-grid-3,
selector .fmg5 .fmg5-bento,
selector .fmg5 .fmg5-gallery{
  display:grid;
  gap:1rem;
}
selector .fmg5 .fmg5-grid-2{grid-template-columns:repeat(2,minmax(0,1fr));}
selector .fmg5 .fmg5-grid-3{grid-template-columns:repeat(3,minmax(0,1fr));}
selector .fmg5 .fmg5-bento{grid-template-columns:1.1fr .9fr 1fr;}
selector .fmg5 .fmg5-gallery{grid-template-columns:repeat(3,minmax(0,1fr));}
selector .fmg5 .fmg5-stat{
  font-size:var(--fmg5-text-xl);
  font-weight:800;
  line-height:1;
  color:var(--fmg5-primary);
}
selector .fmg5 .fmg5-btns{
  display:flex;
  flex-wrap:wrap;
  gap:.75rem;
  margin-top:1.15rem;
}
selector .fmg5 .fmg5-btn a,
selector .fmg5 .fmg5-btn-outline a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:3.125rem;
  padding:.9rem 1.3rem;
  border-radius:999px;
  text-decoration:none;
  font-weight:800;
  line-height:1;
}
selector .fmg5 .fmg5-btn a{
  background:var(--fmg5-gradient-brand);
  color:#fff !important;
  box-shadow:0 14px 30px rgba(246,7,26,.18);
}
selector .fmg5 .fmg5-btn-outline a{
  background:rgba(255,255,255,.9);
  color:var(--fmg5-ink) !important;
  border:1px solid rgba(17,17,20,.12);
}
selector .fmg5 .fmg5-gallery-card .fmg5-ph{
  aspect-ratio:4/3;
  border-radius:var(--fmg5-radius-md);
  background:linear-gradient(135deg,rgba(254,139,21,.18),rgba(246,7,26,.14));
  border:1px dashed rgba(17,17,20,.12);
  display:flex;
  align-items:center;
  justify-content:center;
  text-align:center;
  color:var(--fmg5-ink-soft);
  font-weight:700;
  padding:1rem;
}
selector .fmg5 .fmg5-faq details{
  padding:1rem;
}
selector .fmg5 .fmg5-faq details+details{margin-top:.8rem;}
selector .fmg5 .fmg5-faq summary{
  cursor:pointer;
  font-weight:700;
  color:var(--fmg5-ink);
}
selector .fmg5 .fmg5-products .woocommerce ul.products{
  display:grid !important;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:1rem;
  list-style:none;
  padding:0;
  margin:0;
}
selector .fmg5 .fmg5-products .woocommerce ul.products li.product{
  float:none !important;
  width:auto !important;
  margin:0 !important;
  border:1px solid var(--fmg5-line);
  border-radius:var(--fmg5-radius-lg);
  background:var(--fmg5-gradient-surface);
  box-shadow:var(--fmg5-shadow-sm);
  overflow:hidden;
  padding:1rem;
}
selector .fmg5 .fmg5-products .woocommerce ul.products li.product img{
  width:100%;
  aspect-ratio:1/1;
  object-fit:cover;
  border-radius:var(--fmg5-radius-md);
}
selector .fmg5 .fmg5-products .woocommerce-loop-product__title{
  font-size:var(--fmg5-text-lg);
  line-height:1.15;
  text-transform:uppercase;
  color:var(--fmg5-ink);
}
selector .fmg5 .fmg5-products .price{
  color:var(--fmg5-primary);
  font-weight:800;
  font-size:var(--fmg5-text-md);
}
selector .fmg5 .fmg5-products .button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:3rem;
  padding:.8rem 1.2rem;
  border-radius:999px;
  background:var(--fmg5-gradient-brand);
  color:#fff !important;
  text-decoration:none;
  font-weight:800;
}
selector .fmg5 .fmg5-products .woocommerce ul.products li.product a { pointer-events: none; cursor: default; }
selector .fmg5 #sabores { scroll-margin-top: 120px; }
selector .fmg5 .fmg5-btn a, selector .fmg5 .fmg5-btn-outline a { min-height: 48px; } selector .fmg5 .fmg5-btn a:focus-visible, selector .fmg5 .fmg5-btn-outline a:focus-visible { outline: 3px solid var(--fmg5-primary); outline-offset: 4px; }
selector .woocommerce ul.products li.product a, selector .fmg5 .woocommerce ul.products li.product a { pointer-events: none !important; cursor: default !important; text-decoration: none !important; }
selector .woocommerce ul.products li.product a img { pointer-events: none !important; }
selector .fmg5 .fmg5-products .woocommerce ul.products li.product .button, selector .woocommerce ul.products li.product .button, selector .woocommerce ul.products li.product .add_to_cart_button, selector .woocommerce ul.products li.product .added_to_cart, selector .woocommerce ul.products li.product .ajax_add_to_cart {  display: none !important;  visibility: hidden !important;  opacity: 0 !important;  pointer-events: none !important;  height: 0 !important;  width: 0 !important;  margin: 0 !important;  padding: 0 !important;  overflow: hidden !important;  position: absolute !important; }
@media (max-width:1024px){
  selector .fmg5 .fmg5-grid-3,
  selector .fmg5 .fmg5-bento,
  selector .fmg5 .fmg5-gallery,
  selector .fmg5 .fmg5-products .woocommerce ul.products{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}
@media (max-width:767px){
  selector .fmg5 .fmg5-grid-2,
  selector .fmg5 .fmg5-grid-3,
  selector .fmg5 .fmg5-bento,
  selector .fmg5 .fmg5-gallery,
  selector .fmg5 .fmg5-products .woocommerce ul.products{
    grid-template-columns:1fr;
  }
}
selector .fmg5 .fmg5-products .add_to_cart_button,
selector .fmg5 .fmg5-products .product_type_simple,
selector .fmg5 .fmg5-products .product_type_variable,
selector .fmg5 .fmg5-products .ajax_add_to_cart,
selector .fmg5 .fmg5-products a.button.add_to_cart_button{
  display:none !important;
}
